/**
 * @description
 */
cc.Class({
    extends: require("LMSlots_Symbol_Base"),
    properties: {

    },

    //显示随机符号
    ShowRandomSymbol:function(){
        let cfg = cc.vv.gameData.getGameCfg();
        if (!cfg.randomSymbols) {
            cfg.randomSymbols = cfg.freegameSymbolsCfg[0];
        }
        this._super();
    },

    playWinTweenAction(){
        this._showNode.stopAllActions()
        cc.tween(this._showNode)
            .repeatForever(
                cc.tween()
                    .to(0.35, {opacity: 0})
                    .to(0.35, {opacity: 255})
                    .delay(1)
            )
            .start();
    },

    //停止tween类型的action动画
    stopWinTweenAction(){
        if (this._showNode) {
            this._showNode.active = true
            this._showNode.stopAllActions()
            this._showNode.opacity = 255
        }
    }
});