/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),
    properties: {

    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();

        // 如果有wild图标，那么就要播放stop_ani，然后播放金币飞上去的动画
        let cfg = cc.vv.gameData.getGameCfg();
        for (let i = 0; i < cfg.row; i++) {
            let symbol = this._symbols[i];
            if (symbol.GetShowId() === cfg.wildId) {
                symbol.playStopAnimation();
                cc.vv.gameData.GetSlotsScript().playCoinFlyAnimation(symbol);
            }
        }
    },

    playReelStop() {
        this._super();

        cc.vv.AudioManager.playEff("games/EmperorQin/", "reel_stop", true);

        for (let i = 0; i < cc.vv.gameData.getGameCfg().row; i++) {
            let symbol = this._symbols[i];
            if (symbol.GetShowId() === cc.vv.gameData.getGameCfg().scatterId &&
                cc.vv.gameData.GetSlotsScript().isPlaySymbolScatterAudio(this._reelIdx)) {
                cc.vv.AudioManager.playEff("games/EmperorQin/", "symbol_scatter", true);
                break;
            }
        }
    },

    hasScatter() {
        for (let i = 0; i < cc.vv.gameData.getGameCfg().row; i++) {
            let symbol = this._symbols[i];
            if (symbol.GetShowId() === cc.vv.gameData.getGameCfg().scatterId) {
                return true;
            }
        }
        return false;
    }
});