/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        _successCallback: null,
        _canSelect: false,
    },

    onLoad() {
        for (let i = 1; i < 7; i++) {
            let node = cc.find("node_" + i, this.node);
            node.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canSelect) {
                    return;
                }
                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.gameid = cc.vv.gameData.getGameId();
                req.data = {};
                req.data.rtype = 2;
                req.data.choiceId = i;
                if (i === 6) {
                    cc.vv.AudioManager.playEff("games/EmperorQin/", "fanpai1", true);
                    req.data.choiceItem = this._symbols[Math.floor(Math.random() * 5)];
                } else {
                    cc.vv.AudioManager.playEff("games/EmperorQin/", "fanpai2", true);
                    req.data.choiceItem = this._symbols[i - 1];
                }

                cc.vv.NetManager.send(req, true);
                this._canSelect = false;
            });
        }

        this._symbols = [7, 6, 5, 4, 3];

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, this);
    },

    startGame(success) {
        this.reset();

        this._successCallback = success;

        let free_dialog = this.node.parent;
        free_dialog.active = true;
        let free_bg = free_dialog.getChildByName("free_bg");
        free_bg.opacity = 0;
        free_bg.runAction(cc.fadeTo(0.3, 230));
        this.node.opacity = 0;
        this.node.active = true;
        this.node.runAction(cc.sequence(
            cc.fadeIn(0.3),
            cc.callFunc(()=>{
                cc.find("node_3/spine_light", this.node).active = true;
            }),
            cc.delayTime(0.25),
            cc.callFunc(()=>{
                cc.find("node_2/spine_light", this.node).active = true;
                cc.find("node_6/spine_light", this.node).active = true;
            }),
            cc.delayTime(0.25),
            cc.callFunc(()=>{
                cc.find("node_1/spine_light", this.node).active = true;
                cc.find("node_5/spine_light", this.node).active = true;
            }),
            cc.delayTime(0.25),
            cc.callFunc(()=>{
                cc.find("node_4/spine_light", this.node).active = true;
            })
        ));
        this._canSelect = true;

        if (cc.vv.gameData.isNeedAutoPlay()) {
            let node = cc.find("node_6", this.node);
            cc.tween(node)
                .delay(cc.vv.gameData.getManualAutoPlayTime())
                .call(()=>{
                    if (!this._canSelect) {
                        return;
                    }
                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.gameid = cc.vv.gameData.getGameId();
                    req.data = {};
                    req.data.rtype = 2;
                    req.data.choiceId = 6;
                    cc.vv.AudioManager.playEff("games/EmperorQin/", "fanpai1", true);
                    req.data.choiceItem = this._symbols[Math.floor(Math.random() * 5)];

                    cc.vv.NetManager.send(req, true);
                    this._canSelect = false;
                })
                .start()
        }
    },

    exitGame() {
        let free_dialog = this.node.parent;
        free_dialog.active = false;

        this.node.active = false;
        let cfg = cc.vv.gameData.getGameCfg();
        cfg.randomSymbols = cfg.freegameSymbolsCfg[0];
    },

    async onRcvSubgameData(msg) {
        let data = msg.data;
        let cfg = cc.vv.gameData.getGameCfg();
        if (data.rtype !== 2) {
            return;
        }

        cc.vv.gameData.SetTotalFree(6);
        cc.vv.gameData.SetFreeTime(6);

        cfg.randomSymbols = cfg.freegameSymbolsCfg[data.choiceId];

        let node = cc.find("node_" + data.choiceId, this.node);
        if (node) {
            if (data.choiceId === 6) {
                // 随机的
                node.getChildByName("bg").active = false;
                let spine_choose = node.getChildByName("spine_choose");
                spine_choose.active = true;
                spine_choose.getComponent(sp.Skeleton).clearTracks();
                spine_choose.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
                spine_choose.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation2") {
                        let newNode = cc.instantiate(cc.find("node_" + (this._symbols.indexOf(data.choiceItem) + 1), this.node));
                        newNode.parent = node.getChildByName("result_parent");
                        let pick_light = node.getChildByName("pick_light");
                        newNode.position = cc.v2(0, 0);
                        let spine_select = newNode.getChildByName("spine_select");
                        spine_select.active = true;
                        spine_select.getComponent(sp.Skeleton).clearTracks();
                        spine_select.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                        spine_select.getComponent(sp.Skeleton).setCompleteListener(async ()=>{
                            spine_select.active = false;
                            pick_light.active = true;
                            await this.awaitTime(2);
                            pick_light.active = false;
                            if (this._successCallback) {
                                this._successCallback();
                            }
                        });
                        spine_choose.active = false;
                    }
                });
                let spine = node.getChildByName("spine");
                spine.active = true;
                spine.getComponent(sp.Skeleton).clearTracks();
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
                spine.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                    spine.active = false;
                });
            } else {
                let spine_select = node.getChildByName("spine_select");
                spine_select.active = true;
                spine_select.getComponent(sp.Skeleton).clearTracks();
                spine_select.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                spine_select.getComponent(sp.Skeleton).setCompleteListener(async ()=>{
                    spine_select.active = false;

                    await this.awaitTime(2);

                    if (this._successCallback) {
                        this._successCallback();
                    }
                });
            }
        }
    },

    reset() {
        // 重置所有节点
        for (let i = 1; i < 6; i++) {
            let node = cc.find("node_" + i, this.node);
            node.getChildByName("spine_light").active = false;
        }

        let node = cc.find("node_6", this.node);
        node.getChildByName("bg").active = true;
        node.getChildByName("spine_light").active = false;
        node.getChildByName("result_parent").removeAllChildren();

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, false, this);
    }
});