/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),
    properties: {
        _curCoinInBowlIndex: 0,
        _jackpotGameScript: null,
        _selectFreeTimesScript: null,

        _playBowlLight: true,
        _bowlLightTimer: 10,
        _bg:null,   //聚宝盆位置
        _qinshihuangTransition:null,
    },

    //初始化
    Init:function(){
        this._super();

        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo && deskInfo.coinPot) {
            this.updateCoinInBowl(deskInfo.coinPot);
        }
        this._bg = cc.find("reels_frame/bg",this.node)
        this._qinshihuangTransition = cc.find("transition/qinshihuang", this.node.parent);
        this._qinshihuangTransition.active = false

        Global.SlotsSoundMgr.playEffect("gameStart");
        Global.SlotsSoundMgr.playEffect("KingEnter");
    },

    //重写
    StartMove: function () {
        this._super();

        Global.SlotsSoundMgr.playNormalBgm();
    },

    async ReconnectShow(){
        //是否是免费游戏
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.jackpotGame) {
            this._bottomScript.ShowBtnsByState("unstoped");
           this.reconnectSelectJackpotGame();
        }

        if (deskInfo.freeGameOptions) {
            if (deskInfo.freeGameOptions.state === 1) {
                await this.enterSelectFreeTimes();

                this.cutScenes();

                await this.awaitTime(0.5);

                this._selectFreeTimesScript.exitGame();

                await this.awaitTime(2);

                //free_bgm -> fgbgm
                cc.vv.AudioManager.playBgm("games/EmperorQin/", "fgbgm", true);

                this.CanDoNextRound();
            } else if (deskInfo.freeGameOptions.state === 2) {
                let cfg = cc.vv.gameData.getGameCfg();
                for (let i = 1; i < cfg.freegameSymbolsCfg.length; i++) {
                    let array = cfg.freegameSymbolsCfg[i];
                    if (array.indexOf(deskInfo.freeGameOptions.choiceSymbol) !== -1) {
                        cfg.randomSymbols = array;
                        break;
                    }
                }
                this.ShowGameview(true);

                this.CanDoNextRound();
            }
        }

    },

    async OnSpinEnd() {
        this.ShowWinTrace();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
            if (this._gameInfo && this._gameInfo.jackpotGame) {
                // 触发jackpot game
                await this.triggerJackpotGame();
            }

            if (this.CheckEnterFreeGame()) {
                this._bottomScript.ShowBtnsByState("stopped");

                this.Backup();

                cc.vv.AudioManager.playEff("games/EmperorQin/", "bell", true);
                // 触发免费游戏
                await this.awaitTime(1);

                await this.enterSelectFreeTimes();

                
                this.cutScenes();

                await this.awaitTime(0.5);
                this.ShowGameview(true);

                this._selectFreeTimesScript.exitGame();

                await this.awaitTime(2);

                //free_bgm -> fgbgm
                cc.vv.AudioManager.playBgm("games/EmperorQin/", "fgbgm", true);

                this.CanDoNextRound();
            } else if (this.CheckExtraFreeGame()) {
                this._bottomScript.ShowBtnsByState("stopped");
                await this.awaitTime(1);

                let free_dialog = cc.find("free_dialog", this.node.parent);
                free_dialog.active = true;

                let extra_node = cc.find("extra_node", free_dialog);
                extra_node.active = true;

                //cc.vv.AudioManager.playEff("games/EmperorQin/", "pupup_in", true);
                cc.vv.AudioManager.playEff("games/EmperorQin/", "fgend", true);

                let bg = cc.find("bg", extra_node);
                bg.scale = 0;
                bg.runAction(cc.scaleTo(0.1, 1));

                await this.awaitTime(4);

                cc.vv.AudioManager.playEff("games/EmperorQin/", "popup_out", true);
                bg.runAction(cc.sequence(
                    cc.scaleTo(0.1, 0),
                    cc.callFunc(()=>{
                        extra_node.active = false;
                        free_dialog.active = false;
                    })
                ));

                await this.awaitTime(2);

                this.CanDoNextRound();
            } else {
                if (this.CheckExitFreeGame()) {
                    this._bottomScript.ShowBtnsByState("moveing_1");
                    // 退出免费
                    await this.awaitTime(1);

                    let free_dialog = cc.find("free_dialog", this.node.parent);
                    free_dialog.active = true;

                    cc.vv.AudioManager.playEff("games/EmperorQin/", "jpwin", true);

                    let free_bg = cc.find("free_bg", free_dialog);
                    free_bg.opacity = 0;
                    free_bg.runAction(cc.fadeTo(0.1, 200));

                    let result_node = cc.find("result_node", free_dialog);
                    result_node.active = true;

                    let bg = cc.find("bg", result_node);
                    bg.scale = 0;
                    bg.opacity = 0;
                    bg.runAction(cc.sequence(
                        cc.spawn(
                            cc.fadeIn(0.1),
                            cc.scaleTo(0.1, 1.1),
                        ),
                        cc.scaleTo(0.1, 1),
                    ));

                    let title = cc.find("title", bg);
                    title.opacity = 0;
                    title.runAction(cc.fadeIn(0.3));

                    let coin_bg = cc.find("coin_bg", bg);
                    coin_bg.opacity = 0;
                    coin_bg.runAction(cc.fadeIn(0.3));

                    let coin = cc.find("coin", bg);
                    coin.getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.gameData.GetGameTotalFreeWin());
                    coin.runAction(cc.sequence(
                        cc.delayTime(0.3),
                        cc.scaleTo(0.1, 1.2),
                        cc.scaleTo(0.4, 1),
                    ));

                    let btn_collect = cc.find("btn_collect", bg);
                    btn_collect.opacity = 0;
                    btn_collect.scale = 0;
                    btn_collect.runAction(cc.sequence(
                        cc.delayTime(0.3),
                        cc.spawn(
                            cc.scaleTo(0.1, 1.1),
                            cc.fadeIn(0.1),
                        ),
                        cc.scaleTo(0.1, 1),
                    ));

                    await cc.vv.gameData.awaitTime(0.5);

                    btn_collect.off("click");

                    let func = async ()=>{
                        cc.vv.AudioManager.playEff("games/EmperorQin/", "free_dialog_collect_click", true);
                        bg.runAction(cc.sequence(
                            cc.fadeTo(0.2, 150),
                            cc.spawn(
                                cc.fadeOut(0.2),
                                cc.scaleTo(0.2, 0)
                            )
                        ));

                        await this.awaitTime(0.4);

                        let particle = cc.find("fg_jiesuan", result_node);
                        particle.active = true;

                        await this.awaitTime(0.1);

                        free_bg.runAction(cc.sequence(
                            cc.delayTime(0.4),
                            cc.fadeOut(0.2),
                            cc.callFunc(()=>{
                                particle.active = false;
                            })
                        ));

                        await this.awaitTime(0.3);

                        this.cutScenes();

                        await this.awaitTime(0.5);

                        this.resetAllSymbol();
                        this.Resume();
                        this.ShowGameview(false);

                        await this.awaitTime(2);

                        totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
                        this.ShowBottomWin(totalWinCoin, totalWinCoin, true, ()=>{
                            Global.SlotsSoundMgr.stopBgm();
                            Global.SlotsSoundMgr.playNormalBgm();
                            this.CanDoNextRound();
                        });
                    }
                    cc.vv.gameData.checkAutoPlay(btn_collect, func);
                    btn_collect.on("click", async ()=>{
                        btn_collect.stopAllActions();
                        await func();
                    });
                } else {
                    await this.awaitTime(0.1);

                    this.CanDoNextRound();
                }
            }
        });
    },

    //检查进入免费
    CheckEnterFreeGame:function(){
        return !!(this._gameInfo.freeGameOptions && this._gameInfo.freeGameOptions.state === 1);
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    async triggerFreeGame() {

    },

    cutScenes() {
        cc.vv.AudioManager.playEff("games/EmperorQin/", "ngtowheel", true);
        this._qinshihuangTransition.active = true
        let qinsp = this._qinshihuangTransition.getComponent(sp.Skeleton)
        qinsp.setAnimation(0,"skill",false)
        qinsp.setCompleteListener(()=>{
            this._qinshihuangTransition.active = false
            qinsp.setCompleteListener(null)
        })
    },

    async triggerJackpotGame() {
        return new Promise(async (suc)=>{
            this._bottomScript.ShowBtnsByState("unstoped");
            this._playBowlLight = false;
            if (this._curCoinInBowlIndex === 0) {
                await this.awaitTime(1);
            } else if (this._curCoinInBowlIndex === 1) {
                await this.awaitTime(0.5);
            } else {
                await this.awaitTime(0.1);
            }
            // 进入选择jackpot游戏
            await new Promise((success)=>{
                let bg_bowl = cc.find("reels_frame/bg", this.node);
                let spine_bowl = cc.find("reels_frame/spine_bowl", this.node);
                cc.vv.AudioManager.playEff("games/EmperorQin/", "bowl_open", true);
                cc.vv.AudioManager.playEff("games/EmperorQin/", "wawa", true);
                bg_bowl.active = false;
                spine_bowl.active = true;
                spine_bowl.getComponent(sp.Skeleton).clearTracks();
                spine_bowl.getComponent(sp.Skeleton).setToSetupPose();
                spine_bowl.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
                spine_bowl.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation3") {
                        spine_bowl.getComponent(sp.Skeleton).clearTracks();
                        spine_bowl.getComponent(sp.Skeleton).setToSetupPose();
                        spine_bowl.getComponent(sp.Skeleton).setAnimation(0, "animation4", false);
                    } else if (name === "animation4") {
                        spine_bowl.getComponent(sp.Skeleton).clearTracks();
                        spine_bowl.getComponent(sp.Skeleton).setToSetupPose();
                        spine_bowl.getComponent(sp.Skeleton).setAnimation(0, "animation5", false);
                    } else if (name === "animation5") {
                        spine_bowl.active = false;
                        bg_bowl.active = true;
                        this._curCoinInBowlIndex = 0;
                        success();
                    }
                });
            });

            await this.enterSelectJackpotGame();

            let winCoin = this._jackpotGameScript.getWinCoin();
            let totalWinCoin = cc.vv.gameData.GetGameWin() + winCoin;
            if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin() + winCoin;
            }
            this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
                //bonus_complete -> music_FairyDragon_enter
                cc.vv.AudioManager.playEff("games/EmperorQin/", "music_FairyDragon_enter", true);

                await this.awaitTime(3);

                this.cutScenes();

                await this.awaitTime(0.5);

                this._jackpotGameScript.exitGame();
                this.updateCoinInBowl();

                await this.awaitTime(2);

                this._playBowlLight = true;
                Global.SlotsSoundMgr.playNormalBgm();

                if (suc) {
                    suc();
                }
            });
        });

    },

    async reconnectSelectJackpotGame() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.jackpotGame) {
            await new Promise((success)=>{
                this._jackpotGameScript.reconnect(deskInfo.jackpotGame, success);
            });
        }

        let winCoin = this._jackpotGameScript.getWinCoin();
        let totalWinCoin = deskInfo.winCoin ? deskInfo.winCoin : 0 + winCoin;
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            totalWinCoin = cc.vv.gameData.GetTotalFreeWin() + winCoin;
        }
        this.ShowBottomWin(winCoin, totalWinCoin, true, async ()=>{
            await this.awaitTime(3);

            this.cutScenes();

            await this.awaitTime(0.5);

            this._jackpotGameScript.exitGame();

            await this.awaitTime(2);

            Global.SlotsSoundMgr.playNormalBgm();

            this.CanDoNextRound();
        });
    },

    enterSelectJackpotGame() {
        return new Promise((success)=>{
            this._jackpotGameScript.startGame(success, this._gameInfo.jackpotGame.jackpotValues);
        });
    },

    enterSelectFreeTimes() {
        return new Promise((success)=>{
            this._selectFreeTimesScript.startGame(success);
        });
    },

    setJackpotGameScript(script) {
        this._jackpotGameScript = script;
    },

    setSelectFreeTimesScript(script) {
        this._selectFreeTimesScript = script;
    },

    async playCoinFlyAnimation(symbol) {
        symbol.playStopAnimation();
        let wordPos = symbol.node.convertToWorldSpaceAR(cc.v2(0,0));
        await this.awaitTime(0.3);

        let startPos = this.node.parent.convertToNodeSpaceAR(wordPos)
        let bgPos = this._bg.convertToWorldSpaceAR(cc.v2(0,0))
        let endPos = this.node.parent.convertToNodeSpaceAR(bgPos)
        endPos.y += 150
        cc.vv.AudioManager.playEff("games/EmperorQin/", "coin_fly", true);
        let pianyiPos = [cc.v2(101,56),cc.v2(-95.6,48.6),cc.v2(-47.7,40.2),cc.v2(-44,-124),cc.v2(108.5,28),cc.v2(121.6,-11.6),cc.v2(92.7,-10.7),cc.v2(-135,-49.5)]
        for (let index = 1; index < pianyiPos.length; index++) {
            let pos = cc.v2(startPos.x+ pianyiPos[index].x,startPos.y+ pianyiPos[index].y)
            let newNode = cc.instantiate(cc.find("spine_coin", this.node))
            newNode.active = true
            newNode.parent = this.node.parent
            newNode.position = startPos
            newNode.scale = 1
            newNode.angle = Global.random(1,360)
            let coin = cc.find("coin",newNode)
            coin.active = true
            let star = cc.find("star",newNode)
            star.active = false
            cc.tween(newNode).parallel(cc.tween(newNode).delay(0.2).to(0.65,{scale:0.4},{easing:"quadIn"}).call(()=>{
                    coin.active = false
                    star.active = true
                    star.scale = 2.5
                    newNode.stopAllActions()
                    let starSp = star.getComponent(sp.Skeleton)
                    starSp.setAnimation(0,"animation2",false)
                    starSp.setCompleteListener(()=>{
                        newNode.parent = null
                        starSp.setCompleteListener(null)
                    })
                }),
                cc.tween(newNode).to(0.2,{position:pos},{easing:"quadIn"}).to(0.7,{position:endPos},{easing:"quadIn"})).start()
        }
        this.scheduleOnce(()=>{
            cc.vv.AudioManager.playEff("games/EmperorQin/", "coin_fall", true);
            if (this._gameInfo && this._gameInfo.coinPot) {
                this.updateCoinInBowl(this._gameInfo.coinPot);
            }
        }, 0.9);

    },

    updateCoinInBowl(coinPot) {
        let coin_1 = cc.find("reels_frame/bg/jubaopen/coin_1", this.node);
        let coin_2 = cc.find("reels_frame/bg/jubaopen/coin_2", this.node);
        let coin_3 = cc.find("reels_frame/bg/jubaopen/coin_3", this.node);
        if (coinPot) {
            let percent = coinPot.totalCnt / coinPot.needCnt;
            if (percent < 0.5) {
                // 显示最小的
                this._curCoinInBowlIndex = 0;
                coin_1.opacity = 255;
                coin_2.opacity = 0;
                coin_3.opacity = 0;
            } else if (percent >= 1) {
                // 最多的
                if (this._curCoinInBowlIndex === 0) {
                    coin_2.runAction(cc.fadeIn(0.3));
                    coin_3.runAction(cc.sequence(
                        cc.delayTime(0.3),
                        cc.fadeIn(0.3)
                    ));
                } else if (this._curCoinInBowlIndex === 1) {
                    coin_3.runAction(cc.fadeIn(0.3));
                }
                this._curCoinInBowlIndex = 2;
            } else {
                this._curCoinInBowlIndex = 1;
                coin_2.runAction(cc.fadeIn(0.3));
            }
        } else {
            this._curCoinInBowlIndex = 0;
            coin_1.opacity = 255;
            coin_2.opacity = 0;
            coin_3.opacity = 0;
        }
    },

    isPlaySymbolScatterAudio(colIdx) {
        let result = true;
        for (let i = 0; i < colIdx; i++) {
            let reel = this._reels[i];
            if (!reel.hasScatter()) {
                result = false;
                break;
            }
        }
        return result;
    },

    update (dt) {
        this._super(dt);

        if (this._playBowlLight) {
            this._bowlLightTimer -= dt;
            if (this._bowlLightTimer <= 0) {
                this._bowlLightTimer = 10;

                let spine = cc.find("reels_frame/bg/jubaopen/spine", this.node);
                spine.getComponent(sp.Skeleton).setToSetupPose();
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
            }
        }
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },

    /**
     * 重置所有symbol
     */
    resetAllSymbol() {
        for(let reel of this._reels) {
            for(let s of reel._symbols) {
                s.StartMove();
            }
        }
    }
});