/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        prizepool_grand_num: cc.Node,
        prizepool_major_num: cc.Node,
        prizepool_minor_num: cc.Node,
        prizepool_mini_num: cc.Node,
        result_bg: cc.Node,
        result_grand: cc.Node,
        result_major: cc.Node,
        result_minor: cc.Node,
        result_mini: cc.Node,
        spine_winner: cc.Node,
        particle_celebration: cc.Node,
        coin_parent: cc.Node,

        _successCallback: null,
        _canSelect: false,
        _haveOpenReward: null,
        _winCoin: 0,
    },

    onLoad() {
        this._haveOpenReward = [];
        for (let i = 0; i < 12; i++) {
            let coin_node = cc.find("coin_" + (i + 1), this.node);
            coin_node.on(cc.Node.EventType.TOUCH_END, ()=>{
                if (!this._canSelect) {
                    return;
                }

                for (let reward of this._haveOpenReward) {
                    if (reward.choiceId === (i + 1)) {
                        return;
                    }
                }
                this._canSelect = false;
                
                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.gameid = cc.vv.gameData.getGameId();
                req.data = {};
                req.data.rtype = 1;
                req.data.choiceId = i + 1;

                let success = cc.vv.NetManager.send(req, true);
                if (success) {
                    this._canSelect = false;
                }
            });
        }

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, this);
    },

    async reconnect(jackpotGame, success) {
        cc.vv.AudioManager.playBgm("games/EmperorQin/", "bonus_bgm", true);
        this.reset();
        this._successCallback = success;
        this.node.active = true;
        let gameCfg = cc.vv.gameData.getGameCfg();

        if (jackpotGame.jackpotValues.length >= 4) {
            this.prizepool_mini_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpotValues[0]);
            this.prizepool_minor_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpotValues[1]);
            this.prizepool_major_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpotValues[2]);
            this.prizepool_grand_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpotValues[3]);
        }

        for (let i = 0; i < 12; i++) {
            let coin_node = cc.find("coin_" + (i + 1), this.node);
            let cfg = gameCfg.coinCfg[i];
            let spine = coin_node.getChildByName("coin");
            spine.active = true;
            spine.getComponent(sp.Skeleton).clearTracks();
            spine.getComponent(sp.Skeleton).setToSetupPose();
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation02", true);
            coin_node.position = cfg.endPos;
            coin_node.angle = 0;
        }
        


        for (let i = 0; i < jackpotGame.choiceIdxs.length; i++) {
            let index = jackpotGame.choiceIdxs[i];
            let coin_node = cc.find("coin_" + index, this.node);
            if (coin_node) {
                coin_node.getChildByName("coin").active = false;
                let fuwa = coin_node.getChildByName("fuwa");
                fuwa.active = true;
                let animationName = "animation0" + this._getFuwaAnimationIndex(jackpotGame.choiceItems[i]);
                fuwa.getComponent(sp.Skeleton).clearTracks();
                fuwa.getComponent(sp.Skeleton).setToSetupPose();
                fuwa.getComponent(sp.Skeleton).setAnimation(0, animationName, false);
                this._haveOpenReward.push({choiceId: index, choiceItem: jackpotGame.choiceItems[i]})
            }
        }

        await this.awaitTime(2);
        this._updateAllOpenRewardAnimation();
        this._canSelect = true;
    },

    startGame(success, jackpotValues) {
        cc.vv.AudioManager.playBgm("games/EmperorQin/", "bonus_bgm", true);
        this.reset();

        this._successCallback = success;

        this.node.active = true;

        if (jackpotValues.length >= 4) {
            this.prizepool_mini_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotValues[0]);
            this.prizepool_minor_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotValues[1]);
            this.prizepool_major_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotValues[2]);
            this.prizepool_grand_num.getComponent(cc.Label).string = Global.FormatNumToComma(jackpotValues[3]);
        }

        this.playCoinFly();
    },

    exitGame() {
        this.node.active = false;
    },

    onRcvSubgameData(msg) {
        let data = msg.data;
        if (data.rtype !== 1) {
            return;
        }
        this._haveOpenReward.push({choiceId: data.choiceId, choiceItem: data.choiceItem})
        let coin_node = cc.find("coin_" + data.choiceId, this.node);
        if (coin_node) {
            coin_node.getChildByName("coin").active = false;
            let fuwa = coin_node.getChildByName("fuwa");
            if (data.jackpotGame.winCoin === 0) {
                cc.vv.AudioManager.playEff("games/EmperorQin/", "bonus_coin", true);
            } else {
                cc.vv.AudioManager.playEff("games/EmperorQin/", "bonus_hit", true);
            }

            fuwa.active = true;
            let animationName = "animation0" + this._getFuwaAnimationIndex(data.choiceItem);
            fuwa.getComponent(sp.Skeleton).clearTracks();
            fuwa.getComponent(sp.Skeleton).setToSetupPose();
            fuwa.getComponent(sp.Skeleton).setAnimation(0, animationName, false);
            cc.log("animation name = " + animationName);
            fuwa.getComponent(sp.Skeleton).setCompleteListener(async (track)=>{
                fuwa.getComponent(sp.Skeleton).setCompleteListener();
                let name = track.animation ? track.animation.name : "";
                if (name === animationName) {
                    if (data.jackpotGame.winCoin === 0) {
                        this._canSelect = true;
                        cc.log(this._canSelect);
                        this._updateAllOpenRewardAnimation();
                    } else {
                        // 结束了
                        cc.log(data);
                        this._winCoin = data.jackpotGame.winCoin;

                        cc.vv.gameData.AddCoin(data.jackpotGame.winCoin);

                        await this.awaitTime(2);

                        this.result_bg.active = true;

                        // 生成三个图标来播放动画
                        let array = this._findRewardJackpotItem(data.jackpotGame.jackpotId);
                        for (let arrayElement of array) {
                            let coin_node = cc.find("coin_" + arrayElement.choiceId, this.node);
                            let new_node = cc.instantiate(coin_node);
                            let pos = coin_node.convertToWorldSpaceAR(cc.v2(0, 0));
                            pos = this.coin_parent.convertToNodeSpaceAR(pos);
                            new_node.parent = this.coin_parent;
                            new_node.position = pos;
                            let animationName = "animation0" + this._getFuwaAnimationIndex(arrayElement.choiceItem) + "_2";
                            new_node.getChildByName("coin").active = false;
                            let spine = new_node.getChildByName("fuwa");
                            spine.active = true;
                            spine.getComponent(sp.Skeleton).clearTracks();
                            spine.getComponent(sp.Skeleton).setToSetupPose();
                            spine.getComponent(sp.Skeleton).setAnimation(0, animationName, true);
                        }

                        for (let i = 0; i < data.jackpotGame.restIdxs.length; i++) {
                            let coin_node = cc.find("coin_" + data.jackpotGame.restIdxs[i], this.node);
                            coin_node.getChildByName("coin").active = false;
                            let animationName = "animation0" + this._getFuwaAnimationIndex(data.jackpotGame.restItems[i]);
                            let spine = coin_node.getChildByName("fuwa");
                            spine.active = true;
                            spine.getComponent(sp.Skeleton).clearTracks();
                            spine.getComponent(sp.Skeleton).setToSetupPose();
                            spine.getComponent(sp.Skeleton).setAnimation(0, animationName, false);
                        }

                        await this.awaitTime(2);

                        let resultNode = this._getResultNode(data.jackpotGame.jackpotId);
                        resultNode.getChildByName("num").getComponent(cc.Label).string = Global.FormatNumToComma(data.jackpotGame.winCoin);
                        resultNode.runAction(cc.sequence(
                            cc.fadeIn(2),
                            cc.callFunc(()=>{
                                if (this._successCallback) {
                                    this._successCallback();
                                }
                            })
                        ));

                        await this.awaitTime(1);
                        this.spine_winner.active = true;
                        this.spine_winner.getComponent(sp.Skeleton).setToSetupPose();
                        this.spine_winner.getComponent(sp.Skeleton).setAnimation(0, "animation01", false);
                        this.particle_celebration.active = true;
                    }
                }
            });
        }
    },

    getWinCoin() {
        return this._winCoin;
    },

    reset() {
        // 重置所有金币节点
        let gameCfg = cc.vv.gameData.getGameCfg();
        for (let i = 0; i < 12; i++) {
            let coin_node = cc.find("coin_" + (i + 1), this.node);
            let cfg = gameCfg.coinCfg[i];
            coin_node.angle = cfg.rotation;
            coin_node.getChildByName("coin").active = true;
            coin_node.getChildByName("fuwa").active = false;

            coin_node.position = cc.v2(0, 900);
        }

        // 重置结算界面
        this.result_bg.active = false;
        this.result_grand.opacity = 0;
        this.result_major.opacity = 0;
        this.result_minor.opacity = 0;
        this.result_mini.opacity = 0;

        this.spine_winner.active = false;
        this.particle_celebration.active = false;
        this.coin_parent.removeAllChildren();

        // 重置变量
        this._successCallback = null;
        this._canSelect = false;
        this._haveOpenReward = [];
        this._winCoin = 0;
    },

    playCoinFly() {
        let gameCfg = cc.vv.gameData.getGameCfg();
        for (let i = 0; i < 12; i++) {
            let coin_node = cc.find("coin_" + (i + 1), this.node);
            let cfg = gameCfg.coinCfg[i];
            let spine = coin_node.getChildByName("coin");
            spine.active = true;
            spine.getComponent(sp.Skeleton).clearTracks();
            spine.getComponent(sp.Skeleton).setToSetupPose();
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation01", false);
            spine.getComponent(sp.Skeleton).setCompleteListener((track)=>{
                let name = track.animation ? track.animation.name : "";
                if (name === "animation01") {
                    spine.getComponent(sp.Skeleton).clearTracks();
                    spine.getComponent(sp.Skeleton).setToSetupPose();
                    spine.getComponent(sp.Skeleton).setAnimation(0, "animation02", true);
                }
            });

            coin_node.runAction(cc.sequence(
                cc.spawn(
                    cc.rotateTo(1, 0),
                    cc.moveTo(1, cfg.endPos)
                ),
                cc.delayTime(2),
                cc.callFunc(()=>{
                    if (!this._canSelect) {
                        this._canSelect = true;
                    }
                })
            ))
        }
    },

    _getFuwaAnimationIndex(choiceItem) {
        let result = 0;
        switch (choiceItem) {
            case 1: {
                result = 4;
            }
            break;
            case 2: {
                result = 3;
            }
                break;
            case 3: {
                result = 2;
            }
                break;
            case 4: {
                result = 1;
            }
                break;
        }
        return result;
    },

    _updateAllOpenRewardAnimation() {
        for (let i = 1; i < 5; i++) {
            let array = this._haveOpenReward.filter((item)=>{
                return item.choiceItem === i;
            });
            if (array.length === 2) {
                for (let t of array) {
                    let coin_node = cc.find("coin_" + t.choiceId, this.node);
                    if (coin_node) {
                        let fuwa = coin_node.getChildByName("fuwa");
                        let animationName = "animation0" + this._getFuwaAnimationIndex(t.choiceItem) + "_1";
                        fuwa.getComponent(sp.Skeleton).clearTracks();
                        fuwa.getComponent(sp.Skeleton).setToSetupPose();
                        fuwa.getComponent(sp.Skeleton).setAnimation(0, animationName, true);
                    }
                }
            }
        }  
    },

    _findRewardJackpotItem(jackpotId) {
        return this._haveOpenReward.filter((item)=>{
            return item.choiceItem === jackpotId;
        });
    },

    _getResultNode(jackpotId) {
        let node = null;
        switch (jackpotId) {
            case 1:
                node = this.result_mini;
                break;
            case 2:
                node = this.result_minor;
                break;
            case 3:
                node = this.result_major;
                break;
            case 4:
                node = this.result_grand;
                break;
        }
        return node;
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, false, this);
    }
});